package oracle;
import java.util.*;import java.io.*;import java.nio.*;import org.json.simple.*;import org.json.simple.parser.JSONParser;
import core.game.node.scenery.*;import core.game.world.map.*;import core.game.world.map.build.*;
public class Support {
 public static TreeMap<String,RegionChunk> chunks;public static TreeMap<String,Integer[]> flags;public static Map<Integer,Region> regions;static Map<String,Scenery> nodes;static Region region;static byte[][][]mapscape;static int position;
 static int n(Object x){return((Number)x).intValue();}static int v(Map m,String k,int d){return m.get(k)==null?d:n(m.get(k));}static boolean b(Map m,String k){return Boolean.TRUE.equals(m.get(k));}
 public static Integer[] flags(int key,boolean p){return flags.computeIfAbsent((p?"p:":"m:")+key,k->{Integer[]a=new Integer[64];Arrays.fill(a,p?0:-1);return a;});}
 public static Region forId(int id){return regions.computeIfAbsent(id,k->new Region(k));}
 public static RegionChunk chunk(Location l){String key=l.getChunkBase().toString();return chunks.computeIfAbsent(key,k->new RegionChunk(l.getChunkBase(),0));}
 public static void border(int z,int x,int y,boolean p,int mask,boolean add){Location l=new Location(x,y,z);RegionChunk c=RegionManager.getRegionChunk(l);ChunkFlags f=p?c.getProjectileFlags():c.getFlags();if(add)f.flag(l.getChunkOffsetX(),l.getChunkOffsetY(),mask);else f.unflag(l.getChunkOffsetX(),l.getChunkOffsetY(),mask);}
 public static RegionChunk[][][] regionChunks(Region r){RegionChunk[][][]c=new RegionChunk[8][8][4];for(int x=0;x<8;x++)for(int y=0;y<8;y++)for(int z=0;z<4;z++)c[x][y][z]=chunk(new Location((r.getX()<<6)+(x<<3),(r.getY()<<6)+(y<<3),z));return c;}
 static Map<String,Object> map(Object...p){Map<String,Object>m=new TreeMap<>();for(int i=0;i<p.length;i+=2)m.put((String)p[i],p[i+1]);return m;}
 static Object object(Scenery o){return o==null?null:Arrays.asList(o.getId(),o.getLocation().getX(),o.getLocation().getY(),o.getLocation().getZ(),o.getType(),o.getRotation(),o.isActive(),o.isRenderable(),o instanceof Constructed);}
 static Object snapshot(){List<Object>cells=new ArrayList<>();List<Object>tiles=new ArrayList<>();for(String k:chunks.keySet()){RegionChunk c=chunks.get(k);for(int x=0;x<8;x++)for(int y=0;y<8;y++){if(c.getFlags().getLandscape()[x][y])tiles.add(Arrays.asList(k,x,y));for(int i=0;i<4;i++){Scenery s=c.getStatObjects()[x][y][i],d=c.getObjects()[x][y][i];if(s!=null||d!=null)cells.add(Arrays.asList(k,x,y,i,object(s),object(d)));}}}Map<String,Object>fs=new TreeMap<>();for(String k:flags.keySet())fs.put(k,Arrays.asList(flags.get(k).clone()));Map<String,Object>ns=new TreeMap<>();for(String k:nodes.keySet())ns.put(k,object(nodes.get(k)));return map("cells",cells,"tiles",tiles,"flags",fs,"nodes",ns,"position",position,"count",region.getObjectCount());}
 static Object act(Map a){Scenery o=a.get("node")==null?null:nodes.get(a.get("node"));switch((String)a.get("op")){
 case"add":LandscapeParser.addScenery(o,b(a,"landscape"));return null;
 case"flag":{Location l=o.getLocation();LandscapeParser.flagScenery(chunk(l),v(a,"x",l.getChunkOffsetX()),v(a,"y",l.getChunkOffsetY()),o,b(a,"landscape"),b(a,"store"));return null;}
 case"apply":{Location l=o.getLocation();return LandscapeParser.applyClippingFlagsFor(chunk(l),v(a,"x",l.getChunkOffsetX()),v(a,"y",l.getChunkOffsetY()),o);}
 case"remove":return object(LandscapeParser.removeScenery(o));
 case"active":o.setActive(b(a,"value"));return null;case"renderable":o.setRenderable(b(a,"value"));return null;
 case"parse":{List data=(List)a.get("data");byte[]d=new byte[data.size()];for(int i=0;i<d.length;i++)d[i]=(byte)n(data.get(i));ByteBuffer buffer=ByteBuffer.wrap(d);try{LandscapeParser.parse(region,regionChunks(region),mapscape,buffer,b(a,"store"));}finally{position=buffer.position();}return null;}
 default:throw new IllegalArgumentException();}}
 static void setup(Map input){chunks=new TreeMap<>();flags=new TreeMap<>();regions=new HashMap<>();nodes=new TreeMap<>();position=0;core.cache.def.impl.SceneryDefinition.defs.clear();Map<String,Map>defs=(Map)input.getOrDefault("definitions",new JSONObject());for(String k:defs.keySet()){Map row=defs.get(k);core.cache.def.impl.SceneryDefinition d=core.cache.def.impl.SceneryDefinition.forId(Integer.parseInt(k));d.sizeX=v(row,"sx",1);d.sizeY=v(row,"sy",1);d.clipType=v(row,"clip",2);d.interactable=v(row,"interactable",-1);d.secondBool=b(row,"second");d.projectileClipped=!Boolean.FALSE.equals(row.get("projectile"));d.actions=!Boolean.FALSE.equals(row.get("actions"));}
 Map<String,Map>ns=(Map)input.get("nodes");for(String k:ns.keySet()){Map r=ns.get(k);List l=(List)r.getOrDefault("location",Arrays.asList(3207,3217,0));Scenery o=new Scenery(v(r,"id",1),new Location(n(l.get(0)),n(l.get(1)),n(l.get(2))),v(r,"shape",0),v(r,"rotation",0));nodes.put(k,o);}region=forId((50<<8)|50);region.setObjectCount(v(input,"count",0));mapscape=new byte[4][64][64];for(Object pair:(List)input.getOrDefault("bridges",new ArrayList<>())){List p=(List)pair;mapscape[1][n(p.get(0))][n(p.get(1))]=2;}}
 public static void main(String[]args)throws Exception{try(BufferedReader r=new BufferedReader(new InputStreamReader(System.in,java.nio.charset.StandardCharsets.UTF_8))){String line;while((line=r.readLine())!=null){JSONObject c=(JSONObject)new JSONParser().parse(line);setup(c);List<Object>out=new ArrayList<>();for(Object a:(List)c.get("actions")){Object result=null;String error=null;try{result=act((Map)a);}catch(Throwable e){error=e instanceof BufferUnderflowException?"Decode":e instanceof IndexOutOfBoundsException?"Index":e instanceof IllegalStateException?"State":e instanceof NullPointerException?"Null":e.getClass().getSimpleName();}Map<String,Object>s=(Map)snapshot();s.put("result",result);s.put("error",error);out.add(s);}c.put("expected",out);System.out.println(JSONValue.toJSONString(c));}}}
}
